# region imports
from AlgorithmImports import *
import math
# endregion


class Lot:
    """A private lot of shares owned by one strategy slot.

    Each strategy sells only shares it bought. `pending_buy` / `pending_sell`
    track submitted-but-unfilled market orders so a reason cannot fire twice
    while its order is still in flight (daily bars fill on the next open).
    """

    def __init__(self, name, symbol):
        self.name = name
        self.symbol = symbol
        self.shares = 0
        self.pending_buy = 0
        self.pending_sell = 0

    @property
    def is_empty(self):
        # Buy reasons are evaluated only while the lot is empty.
        return self.shares == 0 and self.pending_buy == 0

    @property
    def is_open(self):
        # Sell reasons are evaluated only while the lot is non-empty.
        return self.shares > 0 and self.pending_sell == 0


class TwoSlotParallelTemplate(QCAlgorithm):
    """One template, 2 slots, no gate. Both slots run independently in parallel.

    Slot 1 - Strategy A (SPY): buy on close crossing above its SMA, invest 40%
             of total portfolio value; sell on close crossing below its SMA.
    Slot 2 - Strategy B (AAPL): buy $20,000 after 3 consecutive red days (only
             if $20,000 cash is available); sell when the 14-day RSI is above 60.
    """

    # --- strategy parameters -------------------------------------------------
    SMA_PERIOD = 20            # period of "its simple moving average" for SPY
    RSI_PERIOD = 14            # 14-day RSI on AAPL
    RSI_SELL_LEVEL = 60.0      # sell Strategy B while RSI is above this level
    RED_DAYS_REQUIRED = 3      # AAPL red for 3 consecutive days
    SLOT1_ALLOCATION = 0.40    # invest 40% of total portfolio value
    SLOT2_CASH_AMOUNT = 20000.0

    TICKERS = ["SPY", "AAPL", "IBM", "BAC", "AIG"]

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1000000)

        # --- subscriptions ---------------------------------------------------
        self.symbols = {}
        for ticker in self.TICKERS:
            equity = self.add_equity(ticker, Resolution.DAILY)
            equity.set_data_normalization_mode(DataNormalizationMode.ADJUSTED)
            self.symbols[ticker] = equity.symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # --- indicators (always updated from data, never gated) --------------
        self.spy_sma = self.sma(self.spy, self.SMA_PERIOD, Resolution.DAILY)
        self.aapl_rsi = self.rsi(self.aapl, self.RSI_PERIOD,
                                 MovingAverageType.WILDERS, Resolution.DAILY)

        # --- continuously maintained market state ----------------------------
        self.prev_close = {}                                  # symbol -> yesterday's close
        self.red_streak = {s: 0 for s in self.symbols.values()}  # consecutive red days
        self.bars_seen = {s: 0 for s in self.symbols.values()}
        self.prev_spy_sma = None                              # yesterday's SMA value

        # --- private lots ----------------------------------------------------
        self.lot_a = Lot("A", self.spy)
        self.lot_b = Lot("B", self.aapl)

        # --- order bookkeeping -----------------------------------------------
        self._orders = {}          # order id -> {lot, side, qty, reserved}
        self._reserved_cash = 0.0  # cash committed to unfilled buy orders

        self.set_warm_up(max(self.SMA_PERIOD, self.RSI_PERIOD) * 3 + 10,
                         Resolution.DAILY)

    # ------------------------------------------------------------------------
    def on_data(self, slice):
        # Collect today's bars for every subscribed ticker.
        bars = {}
        for symbol in self.symbols.values():
            if slice.bars.contains_key(symbol):
                bar = slice.bars[symbol]
                if bar is not None and bar.close > 0:
                    bars[symbol] = bar

        # Snapshot yesterday's values BEFORE the continuous state update.
        prev_spy_close = self.prev_close.get(self.spy)
        prev_spy_sma = self.prev_spy_sma

        # --- update market state continuously (gates never pause this) -------
        for symbol, bar in bars.items():
            last_close = self.prev_close.get(symbol)
            if last_close is not None:
                if bar.close < last_close:
                    self.red_streak[symbol] += 1   # red day
                else:
                    self.red_streak[symbol] = 0    # green or unchanged breaks the streak
            self.prev_close[symbol] = bar.close
            self.bars_seen[symbol] += 1

        # Roll today's SMA into "yesterday" for the next evaluated bar.
        todays_spy_sma = self.spy_sma.current.value if self.spy_sma.is_ready else None
        if self.spy in bars and self.spy_sma.is_ready:
            self.prev_spy_sma = todays_spy_sma

        # --- gating on data / warm-up / indicator readiness -------------------
        if self.is_warming_up:
            return

        # If today's bar is missing for ANY subscribed ticker, skip all rules.
        if len(bars) != len(self.symbols):
            return

        if not self.spy_sma.is_ready or not self.aapl_rsi.is_ready:
            return

        if prev_spy_close is None or prev_spy_sma is None or todays_spy_sma is None:
            return

        # Need enough history for a 3-day red streak to be well defined.
        if self.bars_seen[self.aapl] < self.RED_DAYS_REQUIRED + 1:
            return

        spy_close = bars[self.spy].close
        aapl_close = bars[self.aapl].close

        # ================= SELLS FIRST (all slots) =========================
        # Slot 1 - Strategy A: SPY close crosses below its SMA.
        if self.lot_a.is_open:
            crossed_below = (prev_spy_close >= prev_spy_sma) and (spy_close < todays_spy_sma)
            if crossed_below:
                self._liquidate_lot(self.lot_a)

        # Slot 2 - Strategy B: AAPL 14-day RSI closes above 60.
        if self.lot_b.is_open:
            if self.aapl_rsi.current.value > self.RSI_SELL_LEVEL:
                self._liquidate_lot(self.lot_b)

        # ================= THEN BUYS (in slot order) ========================
        # Slot 1 - Strategy A: SPY close crosses above its SMA -> invest 40% of TPV.
        if self.lot_a.is_empty:
            crossed_above = (prev_spy_close <= prev_spy_sma) and (spy_close > todays_spy_sma)
            if crossed_above:
                target_value = self.portfolio.total_portfolio_value * self.SLOT1_ALLOCATION
                quantity = int(math.floor(target_value / spy_close))
                if quantity > 0:
                    self._submit_buy(self.lot_a, quantity, spy_close)

        # Slot 2 - Strategy B: AAPL red 3 consecutive days -> buy $20,000 if available.
        if self.lot_b.is_empty:
            if self.red_streak[self.aapl] >= self.RED_DAYS_REQUIRED:
                available_cash = self.portfolio.cash - self._reserved_cash
                if available_cash >= self.SLOT2_CASH_AMOUNT:
                    quantity = int(math.floor(self.SLOT2_CASH_AMOUNT / aapl_close))
                    if quantity > 0:
                        self._submit_buy(self.lot_b, quantity, aapl_close)
                # else: do nothing this bar; the reason may fire again later.

    # ------------------------------------------------------------------------
    def _submit_buy(self, lot, quantity, price):
        if not self.securities[lot.symbol].is_tradable:
            return
        ticket = self.market_order(lot.symbol, quantity)
        if ticket is None:
            return
        reserved = quantity * price
        lot.pending_buy += quantity
        self._reserved_cash += reserved
        self._orders[ticket.order_id] = {
            "lot": lot, "side": "buy", "qty": quantity, "reserved": reserved
        }

    def _liquidate_lot(self, lot):
        """Sell the entire private lot (only the shares this strategy bought)."""
        quantity = lot.shares
        if quantity <= 0:
            return
        if not self.securities[lot.symbol].is_tradable:
            return
        ticket = self.market_order(lot.symbol, -quantity)
        if ticket is None:
            return
        lot.pending_sell += quantity
        self._orders[ticket.order_id] = {
            "lot": lot, "side": "sell", "qty": quantity, "reserved": 0.0
        }

    # ------------------------------------------------------------------------
    def on_order_event(self, order_event):
        info = self._orders.get(order_event.order_id)
        if info is None:
            return

        lot = info["lot"]

        if order_event.fill_quantity != 0:
            lot.shares += int(order_event.fill_quantity)
            if lot.shares < 0:
                lot.shares = 0

        if order_event.status in (OrderStatus.FILLED,
                                  OrderStatus.CANCELED,
                                  OrderStatus.INVALID):
            if info["side"] == "buy":
                lot.pending_buy = max(0, lot.pending_buy - info["qty"])
                self._reserved_cash = max(0.0, self._reserved_cash - info["reserved"])
            else:
                lot.pending_sell = max(0, lot.pending_sell - info["qty"])
            del self._orders[order_event.order_id]

