# region imports
from AlgorithmImports import *
import math
# endregion


class TwoSlotParallelStrategyAlgorithm(QCAlgorithm):
    """
    One template, 2 slots, no gate. Both slots run independently, in parallel.

      Slot 1 - Strategy A (SPY): buy when close crosses above its moving average
               (invest 40% of total portfolio value); sell (liquidate lot) when
               close crosses below its moving average.
      Slot 2 - Strategy B (AAPL): buy $20,000 worth when AAPL has been red 3
               consecutive days (only if >= $20,000 cash is available, else do
               nothing); sell (liquidate lot) when the 14-day RSI is above 60.
    """

    TICKERS = ["SPY", "AAPL", "IBM", "BAC", "AIG"]

    # Strategy A parameters
    SMA_PERIOD = 50                 # length of "its moving average" for SPY
    A_ALLOCATION = 0.40             # invest 40% of total portfolio value

    # Strategy B parameters
    B_RED_DAYS = 3                  # red for 3 consecutive days
    B_CASH_PER_BUY = 20000.0        # buy $20,000 if available
    RSI_PERIOD = 14
    B_RSI_SELL_LEVEL = 60.0         # RSI closes above 60

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1000000)

        self.symbols = {}
        for ticker in self.TICKERS:
            equity = self.add_equity(ticker, Resolution.DAILY)
            equity.set_data_normalization_mode(DataNormalizationMode.ADJUSTED)
            self.symbols[ticker] = equity.symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # ---- continuously maintained market state (never gated / never paused)
        self.prev_close = {symbol: None for symbol in self.symbols.values()}
        self.red_streak = {symbol: 0 for symbol in self.symbols.values()}
        self.bar_count = {symbol: 0 for symbol in self.symbols.values()}

        # Indicators are updated manually so that "today's value" is guaranteed
        # to include today's close before any rule is evaluated.
        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(self.RSI_PERIOD)

        # yesterday's values, used for the cross tests
        self.prev_spy_close = None
        self.prev_spy_sma = None

        # ---- private lots (each strategy sells only shares it bought)
        self.lot_a = 0
        self.lot_b = 0
        self.order_owner = {}

    # ------------------------------------------------------------------ data

    def on_data(self, data):
        # Collect today's closes for every subscribed ticker that has a bar.
        closes = {}
        for symbol in self.symbols.values():
            if not data.bars.contains_key(symbol):
                continue
            bar = data.bars[symbol]
            if bar is None or bar.close <= 0:
                continue
            closes[symbol] = float(bar.close)

        # --- update market state from whatever data did arrive (always) ---
        for symbol, close in closes.items():
            previous = self.prev_close[symbol]
            if previous is not None:
                self.red_streak[symbol] = self.red_streak[symbol] + 1 if close < previous else 0
            self.bar_count[symbol] += 1

        if self.spy in closes:
            self.spy_sma.update(IndicatorDataPoint(self.spy, self.time, closes[self.spy]))
        if self.aapl in closes:
            self.aapl_rsi.update(IndicatorDataPoint(self.aapl, self.time, closes[self.aapl]))

        try:
            # If today's bar is missing for ANY subscribed ticker, skip all rules.
            if len(closes) != len(self.symbols):
                return

            if not self._rules_are_formed():
                return

            self._evaluate_rules(closes)
        finally:
            # Remember today's values for tomorrow's comparisons.
            for symbol, close in closes.items():
                self.prev_close[symbol] = close
            if self.spy in closes and self.spy_sma.is_ready:
                self.prev_spy_close = closes[self.spy]
                self.prev_spy_sma = float(self.spy_sma.current.value)

    # ------------------------------------------------------------------ rules

    def _rules_are_formed(self):
        if not self.spy_sma.is_ready or not self.aapl_rsi.is_ready:
            return False
        if self.prev_spy_close is None or self.prev_spy_sma is None:
            return False
        # need enough AAPL history to establish a 3-day red streak
        if self.bar_count[self.aapl] < self.B_RED_DAYS + 1:
            return False
        return True

    def _evaluate_rules(self, closes):
        spy_close = closes[self.spy]
        aapl_close = closes[self.aapl]
        sma_now = float(self.spy_sma.current.value)
        rsi_now = float(self.aapl_rsi.current.value)

        crosses_above = self.prev_spy_close <= self.prev_spy_sma and spy_close > sma_now
        crosses_below = self.prev_spy_close >= self.prev_spy_sma and spy_close < sma_now

        # ---------------- sells are evaluated before buys ----------------
        # Slot 1 - Strategy A: close crosses below its moving average
        if self.lot_a > 0 and crosses_below:
            self._submit(self.spy, -self.lot_a, "A", "sell: SPY close crossed below SMA")

        # Slot 2 - Strategy B: 14-day RSI closes above 60
        if self.lot_b > 0 and rsi_now > self.B_RSI_SELL_LEVEL:
            self._submit(self.aapl, -self.lot_b, "B", "sell: AAPL RSI(14) above 60")

        # ---------------------------- buys ------------------------------
        # Slot 1 - Strategy A: invest 40% of total portfolio value
        if self.lot_a == 0 and crosses_above:
            target = int(math.floor(self.A_ALLOCATION * float(self.portfolio.total_portfolio_value) / spy_close))
            if target > 0:
                self._submit(self.spy, target, "A", "buy: SPY close crossed above SMA")

        # Slot 2 - Strategy B: $20,000 of AAPL if that much cash is available
        if self.lot_b == 0 and self.red_streak[self.aapl] >= self.B_RED_DAYS:
            if float(self.portfolio.cash) >= self.B_CASH_PER_BUY:
                quantity = int(math.floor(self.B_CASH_PER_BUY / aapl_close))
                if quantity > 0:
                    self._submit(self.aapl, quantity, "B", "buy: AAPL red 3 consecutive days")

    # ------------------------------------------------------------- execution

    def _submit(self, symbol, quantity, owner, tag):
        if quantity == 0:
            return
        ticket = self.market_order(symbol, quantity, tag=f"{owner} | {tag}")
        if ticket is None:
            return
        self.order_owner[ticket.order_id] = owner
        if owner == "A":
            self.lot_a = max(0, self.lot_a + quantity)
        else:
            self.lot_b = max(0, self.lot_b + quantity)

    def on_order_event(self, order_event):
        owner = self.order_owner.get(order_event.order_id)
        if owner is None:
            return

        status = order_event.status
        if status in (OrderStatus.INVALID, OrderStatus.CANCELED):
            ticket = self.transactions.get_order_ticket(order_event.order_id)
            unfilled = 0
            if ticket is not None:
                unfilled = int(ticket.quantity - ticket.quantity_filled)
            if owner == "A":
                self.lot_a = max(0, self.lot_a - unfilled)
            else:
                self.lot_b = max(0, self.lot_b - unfilled)
            self.order_owner.pop(order_event.order_id, None)
        elif status == OrderStatus.FILLED:
            self.order_owner.pop(order_event.order_id, None)

